INSERT INTO research_tests (id, grp, name, symbol, period, trades, pf, t_stat, pos_years, verdict, notes, tested_on) VALUES
('S1-day-session-split', 'I', 'Weakness edge split into overnight (18:00→09:30) and day (09:30→15:55) legs, by VIX gate', 'NQ+ES', '2010–2026', 718, 1.43, 2.92, '12/16', 'edge', 'The DAY leg carries MORE than the overnight leg when VIX≥18: NQ +$37.7 PF 1.43 (overnight +$18); weak & VIX≥20 day-only +$52.8 PF 1.60 t 3.3 14/16 yrs, worst yr −$575, maxDD −$2,494, 33 trades/yr, 0.13 ATR (h1 0.11 / h2 0.15). Unconditional day session is NEGATIVE (−$1.2). VIX buckets monotonic above 18 (18–22 +$20, 22–30 +$38, >30 +$95). ES day leg +$16 PF 1.28. The strictly legal intraday form of the only robust edge.', '2026-10-11'),
('S2-day-session-mechanics', 'I', 'Entry/exit timing grid, dip-limit entries, ATR stops/targets on weak & VIX≥20 days', 'NQ', '2010–2026', 517, 1.62, 3.38, '14/16', 'no edge', 'Every alternative subtracts: market at 09:30 → 15:55 +$55 PF 1.62 is the best cell; 10:00 entry +$42, 12:00 exit +$23; dip limits 0.15–0.75 ATR fill 28–69% and make $10–32 at PF 1.1–1.46 (the drift starts at the open); every stop (0.5–1.5 ATR) and target (1–1.5 ATR) lowers avg. Hold to close is the trade.', '2026-10-11'),
('S3-regime-conditioned-fleet', 'I', 'All 5,853 intraday fleet strategies scored on weak & VIX≥20 days only (train <2025-03, test ≥2025-03)', 'NQ', '2021–2026', NULL, NULL, NULL, NULL, 'no edge', '17 of 5,853 have PF>1.3 on those days in both halves (chance); the train leaders (ORB/fib/vt variants, PF 2–3.5 in-sample) are NEGATIVE out of sample; the one consistent id (beta_close, +$11 test) is "hold to close". No intraday mechanic converts the known-at-18:00 drift better than buying the open.', '2026-10-11'),
('S4-at-open-conditions', 'I', 'Every known-at-09:30 feature (gap, prior-day shape, VIX/VIX9D/VIX1D/term/chg5/pct, volume, weekday, FOMC, opex, month turn, earnings nights) vs the day-session return', 'NQ', '2010–2026', NULL, NULL, NULL, NULL, 'weak', 'Long side = the weakness trade (rsi2<22 +$25, prev body<−0.5 ATR +$21, ibs<0.23 +$21, 12/17 yrs). SHORT side after correcting a cost-sign error: VIX 15.4–17.9 ≈ +$16, opex Friday ≈ +$30 (122 trades), post-earnings-night ≈ +$20, Thursday & VIX<18 ≈ +$14, PF ~1.3, 2024–25 carry most of it (h1 ≈ +$5). Small sleeves, not a book.', '2026-10-11'),
('S5-last-hour', 'I', 'Short into the close (15:00/15:30 → 15:55) when the day is down by x ATR; up-day fade', 'NQ+ES', '2010–2026', 429, 1.25, 1.37, '7/17', 'no edge', 'First read (−$16.5 for longs) was the round-trip cost charged to a 5.9-pt drift: short nets +$4–8/MNQ PF 1.15–1.28, 7/17 yrs; 15:15/15:30 entries negative; stops kill it; ES ≈ 0; up-day fade ≈ 0. Low MAE but no edge to size.', '2026-10-11'),
('S6-weekly-consistency-search', 'P', 'All 9,295 NQ/ES strategies ranked on weeks netting ≥$250 at DLL-sized units (train 2021–2025-02, test 2025-03→2026-10)', 'NQ+ES', '2021–2026', NULL, NULL, NULL, NULL, 'no edge', 'Best single: 39% of train weeks ≥$250 — every top-25 strategy is negative out of sample (−$17..−$486/wk). Greedy 4-sleeve portfolio: train 36% → test 35% of weeks with 39% of weeks ≤ −$500. The book (daily hold) alone is 54% of test weeks ≥$250, $837/wk at 4 units.', '2026-10-11'),
('S7-multi-account-cadence', 'P', 'Payout cadence (Select Daily 50K, continuous eval→funded→reset, 2022–26) for 1/2/3 accounts on different sleeves', 'NQ', '2022–2026', NULL, NULL, NULL, NULL, 'weak', 'ONE account on the overnight book: 0.4–0.6 payouts/wk, a payout in ~40% of weeks, 0–0.5 blown/yr. THREE accounts on different sleeves: ~1.2 payouts/wk average but in the same ~35% of weeks (all sleeves lean on the same nights), 1.7 blown/yr. Weekly payouts are not available from any sleeve set; and the book needs an overnight hold Tradeify forbids.', '2026-10-11'),
('S8-intraday-cadence', 'P', 'Payout cadence of the intraday sleeves (day-session weakness long, conditioned day shorts, last-hour short), 1–12 MNQ, with/without stops, 2019–26', 'NQ', '2019–2026', NULL, NULL, NULL, NULL, 'no edge', 'Every sleeve, size and combination: 1–6% of weeks with a payout, 0.2–9 blown/yr, funded 0–60% of days. Arithmetic: edges are 0.05–0.15 ATR/trade against 0.3–0.5 ATR adverse excursion, so the $2,000 trail caps size where a $3,000 eval takes ~a year; stacking sleeves raises blow-ups faster than payouts.', '2026-10-11'),
('S9-crypto-sessions', 'I', 'BTC/ETH hourly 2020–26: hour/weekday seasonality, Asia/EU/US windows after prior-day weakness/strength, 1h momentum by vol regime, autocorrelation, weekends (10 bps RT)', 'crypto', '2020–2026', NULL, NULL, NULL, NULL, 'no edge', 'Hourly seasonality 1–5 bps (under cost); strongest raw session drift ≈ 11 bps (short Asia after a strong close) → ~1 bp net; the 2020–23 +74 bps "buy after −3% day" is −20 bps in 2024–26; 1h next-hour effects ±2–9 bps; daily autocorr −0.05..−0.08. Weekday effects flip between halves. Same edge/MAE wall as NQ, plus Tradeify crypto is CME MBT/MET under the same 16:45 rule.', '2026-10-11'),
('S10-order-flow-ml', 'I', 'Walk-forward LightGBM on per-minute MBO order flow + book quotes (45 features: aggressor delta, cumulative-delta divergence, adds/cancels, qty/order imbalance, top-of-book depth, spread, relative volume, time, VIX, prior day), targets 15/30/60 min, traded non-overlapping in RTH net 1 pt', 'NQ', '2023-03–2026-03', 12086, 0.93, NULL, '2/10', 'no edge', 'Univariate ICs ≤ 0.02 (best: delta/price divergence −0.020, i.e. a faint reversal). OOS Spearman IC −0.004/−0.009/−0.012 at 15/30/60 min; the rule loses in 8–9 of 10 quarters at every horizon (−$285k per NQ over 12k trades at 15 min; MNQ worse). Top model features are the daily ones (prev day, VIX, IBS) — minute order flow adds nothing. The last unmined dataset on the box.', '2026-10-11')
